def transform(grid):
    h, w = len(grid), len(grid[0])

    # Complete a missing uniform row by reflecting the uniform row pattern.
    if all(len(set(row)) == 1 for row in grid):
        out = [row[:] for row in grid]
        for r, row in enumerate(grid):
            if row[0] == 0 and grid[h - 1 - r][0] != 0:
                out[r] = grid[h - 1 - r][:]
        return out

    # Find the diagonal direction and smallest repeating period consistent
    # with all the colored diagonal lines.
    candidates = []
    for kind in (0, 1):  # 0: col-row, 1: row+col
        lines = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = c - r if kind == 0 else r + c
                    lines.setdefault(k, set()).add(color)

        if any(len(colors) != 1 for colors in lines.values()):
            continue
        line_colors = {k: next(iter(colors)) for k, colors in lines.items()}

        for period in range(1, 31):
            mapping = {}
            valid = True
            for k, color in line_colors.items():
                residue = k % period
                if residue in mapping and mapping[residue] != color:
                    valid = False
                    break
                mapping[residue] = color
            if valid and len(mapping) == period:
                candidates.append((period, kind, mapping))
                break

    if candidates:
        _, kind, mapping = min(candidates, key=lambda x: x[0])
        return [[mapping[(c - r if kind == 0 else r + c) % len(mapping)]
                 for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
